import{_ as a,o as e,c as t,a2 as i}from"./chunks/framework.CiKk3sJz.js";const m=JSON.parse('{"title":"漫画 · 第 18 话 Geolocation：拿到坐标之前的三关","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.18-geolocation.md","filePath":"comics/html/EP.18-geolocation.md","lastUpdated":1792579602000}'),c={name:"comics/html/EP.18-geolocation.md"};function r(l,o,n,d,s,h){return e(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="漫画-·-第-18-话-geolocation-拿到坐标之前的三关" tabindex="-1">漫画 · 第 18 话 Geolocation：拿到坐标之前的三关 <a class="header-anchor" href="#漫画-·-第-18-话-geolocation-拿到坐标之前的三关" aria-label="Permalink to &quot;漫画 · 第 18 话 Geolocation：拿到坐标之前的三关&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/07-geolocation">docs/html/07-geolocation.md</a> ｜ 原画：<a href="./EP.18-geolocation.svg">EP.18-geolocation.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，给&quot;附近门店&quot;页接定位——本地 http 测试站点上 <code>navigator.geolocation</code> 居然是 undefined；上线后一进页面就弹授权框，用户反射性点&quot;阻止&quot;，打卡功能集体失灵；还有人反馈点位离实际位置差了几百米。</li><li><strong>标签君</strong>：HTML5 结构师，本话主角。依次拆解安全上下文、权限模型、PositionOptions、三种错误码和坐标系偏移。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>Geolocation API 只回答一个问题：设备现在在哪（经纬度 ± 误差半径）。它不提供地图、不做逆地理编码，且只在<strong>安全上下文</strong>（https 或 localhost）暴露、必须用户授权。定位由 GPS/WiFi/基站/IP 多源融合，<code>accuracy</code> 给出本次结果的可信半径。这是一个错误分支远多于成功分支的 API——本话的核心是把每条失败路径都设计好。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>两道门槛：①Chrome 50+/Firefox 55+ 起只在 https 或 localhost 暴露 API，http 页面 <code>navigator.geolocation</code> 直接是 <code>undefined</code>，不做特性检测就是 TypeError 白屏；②位置是敏感隐私，首次调用触发权限弹窗，进页面就弹的转化率极差，而一旦用户点了拒绝，浏览器不会再弹窗，只能引导去站点设置手动恢复。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三个方法：<code>getCurrentPosition(ok, err, options)</code> 单次定位；<code>watchPosition</code> 在移动时持续回调、返回 watchId；<code>clearWatch(id)</code> 取消（页面隐藏/卸载必须调，否则持续耗电）。PositionOptions 三参数：<code>enableHighAccuracy</code>（尽量用 GPS，更慢更耗电）、<code>timeout</code>（建议必设，默认 Infinity 会让用户干等）、<code>maximumAge</code>（可接受多久以内的缓存）。成功回调给 <code>coords.latitude/longitude/accuracy</code>——accuracy 是 68% 置信圆半径，是判断&quot;这结果能不能用&quot;的关键字段。错误回调只信稳定的 <code>err.code</code>：1 拒绝授权、2 定位不可用、3 超时。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>三件落地大事：①<strong>坐标系</strong>——API 直出 WGS-84，高德/腾讯用 GCJ-02、百度用 BD-09，不转换直接上图点位偏移几百米，来源端和消费端必须统一坐标系；②<strong>授权姿势</strong>——弹窗绑定&quot;定位&quot;按钮的用户手势，用 <code>permissions.query</code> 预检（granted 静默定位、denied 显示开启引导），accuracy 大于阈值的结果直接判不可信；③<strong>降级链</strong>——精确定位失败 → 服务端 IP 城市级定位 → 手动选择城市，保证功能永远有出路。开发阶段先接 Mock（把成功回调抽象注入，真实/Mock 共用同一套渲染逻辑），不受环境与权限干扰。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>先特性检测、必设 timeout；错误只按 err.code 分支，denied 别反复弹，改展示开启引导。</li><li>accuracy 先过滤再消费；权限弹窗绑用户手势；watchPosition 用完必须 clearWatch。</li><li>API 出 WGS84、国内地图吃 GCJ-02/BD-09，两端坐标系不统一必偏几百米。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：用户在公司里打卡却被判定&quot;距公司 1.2 公里&quot;，代码算距离的公式没错，最可能漏掉了哪一步？</p><p><strong>答</strong>：漏掉了对 <code>coords.accuracy</code> 的校验。定位结果是&quot;经纬度 + 误差半径&quot;的组合：室内信号弱时系统可能返回一个 accuracy 高达 800 米的粗略坐标，用这个点去算围栏距离，得出&quot;1.2 公里&quot;在数学上正确、在业务上无意义。正确做法是消费坐标前先过滤精度——accuracy 大于业务阈值（如 200 米）就判定结果不可信，提示&quot;信号弱，请到窗边重试&quot;，而不是拿去算距离。此外还要排查 WGS84/GCJ-02 坐标系是否统一：围栏坐标若按高德后台（GCJ-02）标定，而浏览器返回 WGS84 未转换，全体点位会稳定偏移约 500 米。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>单次定位全流程（真实 + Mock 双路径）：<a href="./../../examples/html/07-geolocation/index-01-get-current-position.html">examples/html/07-geolocation/index-01-get-current-position.html</a></li><li>watchPosition 持续定位 + 内联 SVG 轨迹绘制：<a href="./../../examples/html/07-geolocation/index-02-watch-position.html">index-02-watch-position.html</a></li><li>PositionOptions 调参面板 + 三种错误码演练：<a href="./../../examples/html/07-geolocation/index-03-options-errors.html">index-03-options-errors.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 19 话《拖放 API》——从桌面拖一张图片进网页：dragstart 到 drop 的事件链与 dataTransfer 的规矩。</p>',22)])])}const p=a(c,[["render",r]]);export{m as __pageData,p as default};
